#include <stdio.h>

void bump(int v)
{
    v = v + 1;
}

int main(void)
{
    int x = 3;

    bump(x);
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>

void bump(int *p)
{
    *p = *p + 1;
}

int main(void)
{
    int x = 3;

    bump(&x);
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>

int f(int n)
{
    if (n <= 1)
        return 1;
    return n * f(n - 1);
}

int main(void)
{
    printf("%d\n", f(4));
    return 0;
}

#include <stdio.h>

void twice(int *v, int n)
{
    for (int i = 0; i < n; i++)
        v[i] *= 2;
}

int main(void)
{
    int a[3] = {1, 2, 3};

    twice(a, 3);
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return 0;
}

